package com.howmanymore;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Skill;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.skillcalculator.skills.AgilityAction;
import net.runelite.client.plugins.skillcalculator.skills.AgilityBonus;
import net.runelite.client.plugins.skillcalculator.skills.ConstructionAction;
import net.runelite.client.plugins.skillcalculator.skills.ConstructionBonus;
import net.runelite.client.plugins.skillcalculator.skills.CookingAction;
import net.runelite.client.plugins.skillcalculator.skills.CraftingAction;
import net.runelite.client.plugins.skillcalculator.skills.FarmingAction;
import net.runelite.client.plugins.skillcalculator.skills.FarmingBonus;
import net.runelite.client.plugins.skillcalculator.skills.FiremakingAction;
import net.runelite.client.plugins.skillcalculator.skills.FiremakingBonus;
import net.runelite.client.plugins.skillcalculator.skills.FishingAction;
import net.runelite.client.plugins.skillcalculator.skills.FishingBonus;
import net.runelite.client.plugins.skillcalculator.skills.FletchingAction;
import net.runelite.client.plugins.skillcalculator.skills.HerbloreAction;
import net.runelite.client.plugins.skillcalculator.skills.HunterAction;
import net.runelite.client.plugins.skillcalculator.skills.MagicAction;
import net.runelite.client.plugins.skillcalculator.skills.MiningAction;
import net.runelite.client.plugins.skillcalculator.skills.MiningBonus;
import net.runelite.client.plugins.skillcalculator.skills.PrayerAction;
import net.runelite.client.plugins.skillcalculator.skills.PrayerBonus;
import net.runelite.client.plugins.skillcalculator.skills.RunecraftAction;
import net.runelite.client.plugins.skillcalculator.skills.RunecraftBonus;
import net.runelite.client.plugins.skillcalculator.skills.SailingAction;
import net.runelite.client.plugins.skillcalculator.skills.SailingBonus;
import net.runelite.client.plugins.skillcalculator.skills.SkillAction;
import net.runelite.client.plugins.skillcalculator.skills.SkillBonus;
import net.runelite.client.plugins.skillcalculator.skills.SmithingAction;
import net.runelite.client.plugins.skillcalculator.skills.SmithingBonus;
import net.runelite.client.plugins.skillcalculator.skills.ThievingAction;
import net.runelite.client.plugins.skillcalculator.skills.WoodcuttingAction;
import net.runelite.client.plugins.skillcalculator.skills.WoodcuttingBonus;

// Every reference to the Skill Calculator lives here, so MethodCatalog can catch the error if an update moves it.
final class CalculatorMethods
{
	private CalculatorMethods()
	{
	}

	static Map<Skill, List<MethodCatalog.Method>> load(ItemManager itemManager)
	{
		Map<Skill, List<MethodCatalog.Method>> methods = new EnumMap<>(Skill.class);
		for (Skill skill : Skill.values())
		{
			SkillBonus[] bonuses = bonuses(skill);
			List<MethodCatalog.Method> skillMethods = new ArrayList<>();
			for (SkillAction action : actions(skill))
			{
				List<MethodCatalog.Bonus> applicable = new ArrayList<>();
				for (SkillBonus bonus : bonuses)
				{
					if (action.isBonusApplicable(bonus))
					{
						applicable.add(new MethodCatalog.Bonus(((Enum<?>) bonus).name(), bonus.getName(),
							Math.round(bonus.getValue() * 1e6) / 1e6));
					}
				}
				skillMethods.add(new MethodCatalog.Method(((Enum<?>) action).name(), action.getName(itemManager),
					action.getLevel(), Math.round(action.getXp() * 10) / 10.0, Collections.unmodifiableList(applicable)));
			}
			if (!skillMethods.isEmpty())
			{
				methods.put(skill, Collections.unmodifiableList(skillMethods));
			}
		}
		return methods;
	}

	private static SkillAction[] actions(Skill skill)
	{
		switch (skill)
		{
			case AGILITY:
				return AgilityAction.values();
			case CONSTRUCTION:
				return ConstructionAction.values();
			case COOKING:
				return CookingAction.values();
			case CRAFTING:
				return CraftingAction.values();
			case FARMING:
				return FarmingAction.values();
			case FIREMAKING:
				return FiremakingAction.values();
			case FISHING:
				return FishingAction.values();
			case FLETCHING:
				return FletchingAction.values();
			case HERBLORE:
				return HerbloreAction.values();
			case HUNTER:
				return HunterAction.values();
			case MAGIC:
				return MagicAction.values();
			case MINING:
				return MiningAction.values();
			case PRAYER:
				return PrayerAction.values();
			case RUNECRAFT:
				return RunecraftAction.values();
			case SAILING:
				return SailingAction.values();
			case SMITHING:
				return SmithingAction.values();
			case THIEVING:
				return ThievingAction.values();
			case WOODCUTTING:
				return WoodcuttingAction.values();
			default:
				return new SkillAction[0];
		}
	}

	private static SkillBonus[] bonuses(Skill skill)
	{
		switch (skill)
		{
			case AGILITY:
				return AgilityBonus.values();
			case CONSTRUCTION:
				return ConstructionBonus.values();
			case FARMING:
				return FarmingBonus.values();
			case FIREMAKING:
				return FiremakingBonus.values();
			case FISHING:
				return FishingBonus.values();
			case MINING:
				return MiningBonus.values();
			case PRAYER:
				return PrayerBonus.values();
			case RUNECRAFT:
				return RunecraftBonus.values();
			case SAILING:
				return SailingBonus.values();
			case SMITHING:
				return SmithingBonus.values();
			case WOODCUTTING:
				return WoodcuttingBonus.values();
			default:
				return new SkillBonus[0];
		}
	}
}

package com.howmanymore;

import lombok.Data;
import lombok.NoArgsConstructor;
import net.runelite.api.Skill;

// Saved as JSON in the RuneScape profile config, so keep field names stable.
@Data
@NoArgsConstructor
class Goal
{
	private String id;
	private Skill skill;
	private int targetXp;
	// XP when the goal was set, where the progress bar starts.
	private int startXp;
	// A Skill Calculator action name, or MethodCatalog.CUSTOM / MethodCatalog.AUTO.
	private String method;
	private double customXp;
	// A Skill Calculator bonus name, or null.
	private String bonus;
	private boolean reached;

	Goal copy()
	{
		Goal goal = new Goal();
		goal.id = id;
		goal.skill = skill;
		goal.targetXp = targetXp;
		goal.startXp = startXp;
		goal.method = method;
		goal.customXp = customXp;
		goal.bonus = bonus;
		goal.reached = reached;
		return goal;
	}
}

package com.howmanymore;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.api.Experience;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.components.ProgressBar;
import net.runelite.client.util.QuantityFormatter;

// One goal in the sidebar: what's left, a progress bar, and its method.
class GoalCard extends JPanel
{
	private static final int PROGRESS_STEPS = 1000;
	private static final Color PROGRESS_BACKGROUND = new Color(61, 56, 49);
	// Light, for the dark bar.
	private static final Color BAND_COLOR = new Color(255, 255, 255, 24);

	private final JLabel countLabel = new JLabel();
	private final JLabel detailLabel = new JLabel();
	private final BandedProgressBar progressBar = new BandedProgressBar();

	GoalCard(HowManyMorePlugin plugin, SkillIconManager skillIconManager, GoalStatus status)
	{
		Goal goal = status.getGoal();
		setLayout(new DynamicGridLayout(0, 1, 0, 6));
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setBorder(new EmptyBorder(8, 8, 8, 8));

		JLabel title = new JLabel(status.getTargetLabel(), new ImageIcon(skillIconManager.getSkillImage(goal.getSkill(), true)),
			JLabel.LEFT);
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setIconTextGap(6);

		JButton remove = new JButton("Remove");
		remove.setFont(FontManager.getRunescapeSmallFont());
		remove.setFocusable(false);
		remove.addActionListener(e -> plugin.removeGoal(goal.getId()));

		JPanel header = new JPanel(new BorderLayout());
		header.setOpaque(false);
		header.add(title, BorderLayout.CENTER);
		header.add(remove, BorderLayout.EAST);

		countLabel.setFont(FontManager.getRunescapeBoldFont());
		detailLabel.setFont(FontManager.getRunescapeSmallFont());
		detailLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		progressBar.setMaximumValue(PROGRESS_STEPS);
		progressBar.setBackground(PROGRESS_BACKGROUND);
		progressBar.setPreferredSize(new Dimension(0, 16));

		MethodPicker methodPicker = new MethodPicker(picker -> plugin.setMethod(goal.getId(), picker.getMethodId(),
			picker.getCustomXp(), picker.getBonusId()));
		methodPicker.setChoices(plugin.getCatalog().methods(goal.getSkill()), goal.getMethod(), goal.getCustomXp(),
			goal.getBonus());

		add(header);
		add(countLabel);
		add(detailLabel);
		add(progressBar);
		add(methodPicker);
		update(status);
	}

	void update(GoalStatus status)
	{
		if (status.isReached())
		{
			countLabel.setText("Goal reached!");
			countLabel.setForeground(ColorScheme.PROGRESS_COMPLETE_COLOR);
		}
		else if (status.getActionsLeft() < 0)
		{
			countLabel.setText(status.getMissingCountReason());
			countLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		}
		else
		{
			countLabel.setText(QuantityFormatter.formatNumber(status.getActionsLeft()) + " left");
			countLabel.setForeground(ColorScheme.BRAND_ORANGE);
		}

		String detail = QuantityFormatter.formatNumber(status.getXpLeft()) + " XP left";
		if (status.getXpEach() > 0)
		{
			detail += ", " + GoalMath.formatXp(status.getXpEach()) + " XP each";
		}
		detailLabel.setText(detail);

		int targetLevel = GoalMath.targetLevel(status.getGoal().getTargetXp());
		progressBar.goal = status.getGoal();
		progressBar.setValue((int) Math.round(status.getProgress() * PROGRESS_STEPS));
		progressBar.setLeftLabel("Lvl " + Experience.getLevelForXp(status.getCurrentXp()));
		progressBar.setRightLabel(targetLevel > 0
			? "Lvl " + targetLevel
			: QuantityFormatter.quantityToStackSize(status.getGoal().getTargetXp()));
		progressBar.setCenterLabel((int) Math.floor(status.getProgress() * 100) + "%");
		progressBar.setForeground(status.isReached() ? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.BRAND_ORANGE);
	}

	// RuneLite's progress bar with level bands under its fill and labels.
	private static class BandedProgressBar extends ProgressBar
	{
		private Goal goal;

		@Override
		protected void paintComponent(Graphics g)
		{
			super.paintComponent(g);
			if (goal != null)
			{
				// The fill is painted over the bands, so they only show on the part still to go.
				LevelBands.paint(g, BAND_COLOR, goal.getStartXp(), goal.getTargetXp(), 0, 0, getWidth(), getHeight(), 0);
			}
		}
	}
}

package com.howmanymore;

import java.util.Locale;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import net.runelite.client.util.QuantityFormatter;

final class GoalMath
{
	// XP per action is shown in tenths in game; this absorbs float noise like 269.7f -> 269.70001.
	private static final double EPSILON = 1e-6;

	private GoalMath()
	{
	}

	static int xpLeft(int currentXp, int targetXp)
	{
		return Math.max(0, targetXp - currentXp);
	}

	// -1 when the XP per action isn't known yet.
	static int actionsLeft(int xpLeft, double xpEach)
	{
		if (xpEach <= 0)
		{
			return -1;
		}
		return (int) Math.ceil(xpLeft / xpEach - EPSILON);
	}

	static double progress(int startXp, int currentXp, int targetXp)
	{
		if (targetXp <= startXp)
		{
			return 1;
		}
		double progress = (double) (currentXp - startXp) / (targetXp - startXp);
		return Math.max(0, Math.min(1, progress));
	}

	// The level whose XP is exactly targetXp, or 0 for a plain XP target.
	static int targetLevel(int targetXp)
	{
		for (int level = 2; level <= Experience.MAX_VIRT_LEVEL; level++)
		{
			int xp = Experience.getXpForLevel(level);
			if (xp == targetXp)
			{
				return level;
			}
			if (xp > targetXp)
			{
				break;
			}
		}
		return 0;
	}

	static String targetLabel(Skill skill, int targetXp)
	{
		int level = targetLevel(targetXp);
		return level > 0
			? level + " " + skill.getName()
			: QuantityFormatter.quantityToStackSize(targetXp) + " " + skill.getName() + " XP";
	}

	/**
	 * Reads a goal typed as a level ("70") or an XP amount ("1,500,000", "1.5m", "500k").
	 * Numbers up to the max virtual level are levels. Returns the target XP, or -1 if the text isn't a valid goal.
	 */
	static int parseTarget(String text)
	{
		if (text == null)
		{
			return -1;
		}

		String value = text.trim().toLowerCase(Locale.ROOT).replace(",", "").replace(" ", "");
		double multiplier = 1;
		if (value.endsWith("k"))
		{
			multiplier = 1_000;
		}
		else if (value.endsWith("m"))
		{
			multiplier = 1_000_000;
		}
		if (multiplier > 1)
		{
			value = value.substring(0, value.length() - 1);
		}

		double number;
		try
		{
			number = Double.parseDouble(value);
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
		if (Double.isNaN(number) || number <= 0)
		{
			return -1;
		}

		if (multiplier == 1 && number <= Experience.MAX_VIRT_LEVEL)
		{
			if (number != Math.floor(number) || number < 2)
			{
				return -1;
			}
			return Experience.getXpForLevel((int) number);
		}

		double xp = Math.round(number * multiplier);
		return xp > Experience.MAX_SKILL_XP ? -1 : (int) xp;
	}

	// The XP each typed for a custom goal, or 0 if it isn't a positive number.
	static double parseXpEach(String text)
	{
		try
		{
			double xp = Double.parseDouble(text.trim().replace(",", ""));
			return Double.isNaN(xp) || Double.isInfinite(xp) || xp <= 0 ? 0 : xp;
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	// "348" or "269.7": up to two decimals, without trailing zeros.
	static String formatXp(double xp)
	{
		String text = String.format(Locale.ROOT, "%.2f", xp);
		text = text.replaceAll("0+$", "");
		return text.endsWith(".") ? text.substring(0, text.length() - 1) : text;
	}
}

package com.howmanymore;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import net.runelite.api.Experience;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentOrientation;
import net.runelite.client.ui.overlay.components.ImageComponent;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.ProgressBarComponent;
import net.runelite.client.ui.overlay.components.SplitComponent;
import net.runelite.client.util.QuantityFormatter;

class GoalOverlay extends OverlayPanel
{
	private static final int WIDTH = 170;
	private static final Color COUNT_COLOR = Color.YELLOW;
	private static final Color REACHED_COLOR = ColorScheme.PROGRESS_COMPLETE_COLOR;
	private static final Color HINT_COLOR = Color.LIGHT_GRAY;
	// Dark, for RuneLite's light overlay bar.
	private static final Color BAND_COLOR = new Color(0, 0, 0, 45);
	private static final Color CLEAR = new Color(0, 0, 0, 0);

	private final HowManyMorePlugin plugin;
	private final HowManyMoreConfig config;
	private final SkillIconManager skillIconManager;

	@Inject
	GoalOverlay(HowManyMorePlugin plugin, HowManyMoreConfig config, SkillIconManager skillIconManager)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		this.skillIconManager = skillIconManager;
		setPosition(OverlayPosition.TOP_LEFT);
		panelComponent.setPreferredSize(new Dimension(WIDTH, 0));
		panelComponent.setGap(new Point(0, 4));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showHud() || !plugin.isStatsReady())
		{
			return null;
		}

		long hideAfter = TimeUnit.MINUTES.toMillis(config.hideAfterIdle());
		for (GoalStatus status : plugin.getStatuses())
		{
			if (hideAfter == 0 || plugin.millisSinceGain(status.getSkill()) <= hideAfter)
			{
				addGoal(status);
			}
		}

		if (panelComponent.getChildren().isEmpty())
		{
			return null;
		}
		return super.render(graphics);
	}

	private void addGoal(GoalStatus status)
	{
		LayoutableRenderableEntity text = SplitComponent.builder()
			.first(LineComponent.builder()
				.left(status.getMethodName() != null ? status.getMethodName() : status.getSkill().getName())
				.build())
			.second(countLine(status))
			.orientation(ComponentOrientation.VERTICAL)
			.build();

		if (config.showXpLeft() && !status.isReached())
		{
			text = SplitComponent.builder()
				.first(text)
				.second(LineComponent.builder()
					.left("XP left")
					.right(QuantityFormatter.formatNumber(status.getXpLeft()))
					.build())
				.orientation(ComponentOrientation.VERTICAL)
				.build();
		}

		panelComponent.getChildren().add(SplitComponent.builder()
			.first(new ImageComponent(skillIconManager.getSkillImage(status.getSkill(), true)))
			.second(text)
			.orientation(ComponentOrientation.HORIZONTAL)
			.gap(new Point(4, 0))
			.build());

		if (config.showProgressBar())
		{
			panelComponent.getChildren().add(new GoalBar(status));
		}
	}

	private static LineComponent countLine(GoalStatus status)
	{
		if (status.isReached())
		{
			return LineComponent.builder().left("Goal reached!").leftColor(REACHED_COLOR).build();
		}
		if (status.getActionsLeft() < 0)
		{
			return LineComponent.builder().left(status.getMissingCountReason()).leftColor(HINT_COLOR).build();
		}
		return LineComponent.builder()
			.left("To " + shortTarget(status.getGoal().getTargetXp()))
			.right(QuantityFormatter.formatNumber(status.getActionsLeft()))
			.rightColor(COUNT_COLOR)
			.build();
	}

	// RuneLite's overlay bar with level bands: the bar without its text, then the bands, then only the text.
	private static class GoalBar implements LayoutableRenderableEntity
	{
		private final GoalStatus status;
		private final Rectangle bounds = new Rectangle();
		private Point preferredLocation = new Point();
		private Dimension preferredSize = new Dimension();

		GoalBar(GoalStatus status)
		{
			this.status = status;
		}

		@Override
		public Dimension render(Graphics2D graphics)
		{
			ProgressBarComponent bar = bar();
			bar.setLabelDisplayMode(ProgressBarComponent.LabelDisplayMode.TEXT_ONLY);
			bar.setCenterLabel("");
			if (status.isReached())
			{
				bar.setForegroundColor(REACHED_COLOR);
			}
			Dimension size = bar.render(graphics);

			// The fill's width, worked out as ProgressBarComponent does it.
			int fill = (int) (size.width * Math.min(1, status.getProgress() * 100 / 100));
			Goal goal = status.getGoal();
			LevelBands.paint(graphics, BAND_COLOR, goal.getStartXp(), goal.getTargetXp(), preferredLocation.x,
				preferredLocation.y, size.width, size.height, fill);

			ProgressBarComponent text = bar();
			text.setForegroundColor(CLEAR);
			text.setBackgroundColor(CLEAR);
			text.setLeftLabel("Lvl " + Experience.getLevelForXp(status.getCurrentXp()));
			int targetLevel = GoalMath.targetLevel(goal.getTargetXp());
			text.setRightLabel(targetLevel > 0 ? "Lvl " + targetLevel : shortTarget(goal.getTargetXp()));
			text.render(graphics);

			bounds.setLocation(preferredLocation);
			bounds.setSize(size);
			return size;
		}

		private ProgressBarComponent bar()
		{
			ProgressBarComponent bar = new ProgressBarComponent();
			bar.setMaximum(100);
			bar.setValue(status.getProgress() * 100);
			bar.setPreferredLocation(preferredLocation);
			bar.setPreferredSize(preferredSize);
			return bar;
		}

		@Override
		public void setPreferredLocation(Point preferredLocation)
		{
			this.preferredLocation = preferredLocation;
		}

		@Override
		public void setPreferredSize(Dimension preferredSize)
		{
			this.preferredSize = preferredSize;
		}

		@Override
		public Rectangle getBounds()
		{
			return bounds;
		}
	}

	// "70" for a level goal, "1.5M XP" for an XP goal.
	private static String shortTarget(int targetXp)
	{
		int level = GoalMath.targetLevel(targetXp);
		return level > 0 ? Integer.toString(level) : QuantityFormatter.quantityToStackSize(targetXp) + " XP";
	}
}

package com.howmanymore;

import javax.annotation.Nullable;
import lombok.Value;
import net.runelite.api.Skill;

// A snapshot of one goal's progress, shared read-only with the HUD and the sidebar.
@Value
class GoalStatus
{
	// A copy, so the sidebar can read it off the client thread.
	Goal goal;
	// The training method's name, or null for custom and auto goals.
	@Nullable
	String methodName;
	double xpEach;
	int currentXp;
	int xpLeft;
	// -1 when the XP per action isn't known yet.
	int actionsLeft;
	double progress;

	Skill getSkill()
	{
		return goal.getSkill();
	}

	boolean isReached()
	{
		return goal.isReached();
	}

	String getTargetLabel()
	{
		return GoalMath.targetLabel(goal.getSkill(), goal.getTargetXp());
	}

	// Why the count is missing, when actionsLeft is -1.
	String getMissingCountReason()
	{
		if (MethodCatalog.AUTO.equals(goal.getMethod()))
		{
			return "Gain XP once to count";
		}
		if (MethodCatalog.CUSTOM.equals(goal.getMethod()))
		{
			return "Set the XP each";
		}
		return "Pick a method";
	}
}

package com.howmanymore;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Notification;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(HowManyMoreConfig.GROUP)
public interface HowManyMoreConfig extends Config
{
	// The plugin's old name. Saved goals and settings live under it, so it stays.
	String GROUP = "goal-counter";

	@ConfigItem(keyName = "showHud", name = "Show HUD",
		description = "Show your goals and the actions left on screen. Set goals in the How Many More sidebar panel",
		position = 0)
	default boolean showHud()
	{
		return true;
	}

	@ConfigItem(keyName = "showProgressBar", name = "Show progress bar",
		description = "Show a bar under each goal, from where you were when you set it to the goal",
		position = 1)
	default boolean showProgressBar()
	{
		return true;
	}

	@ConfigItem(keyName = "showXpLeft", name = "Show XP left",
		description = "Show the XP left as well as the actions left",
		position = 2)
	default boolean showXpLeft()
	{
		return false;
	}

	@Range(max = 120)
	@Units(Units.MINUTES)
	@ConfigItem(keyName = "hideAfterIdle", name = "Hide when not training",
		description = "Hide a goal from the HUD after this many minutes without XP in its skill. 0 always shows it",
		position = 3)
	default int hideAfterIdle()
	{
		return 0;
	}

	@ConfigItem(keyName = "goalReachedNotification", name = "Goal reached notification",
		description = "Notify you when you reach a goal",
		position = 4)
	default Notification goalReachedNotification()
	{
		return Notification.ON;
	}
}

package com.howmanymore;

import java.awt.BorderLayout;
import java.awt.Component;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.swing.DefaultListCellRenderer;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.border.EmptyBorder;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

// The sidebar: a form to add a goal, then a card per goal. Only touched on the Swing thread.
class HowManyMorePanel extends PluginPanel
{
	private final HowManyMorePlugin plugin;
	private final SkillIconManager skillIconManager;

	private final JComboBox<Skill> skillBox = new JComboBox<>();
	private final JTextField targetField = new JTextField();
	private final MethodPicker newMethod = new MethodPicker(null);
	private final JLabel errorLabel = new JLabel();
	private final JPanel goalList = new JPanel(new DynamicGridLayout(0, 1, 0, 8));
	private final JLabel emptyLabel = new JLabel();
	private final Map<String, GoalCard> cards = new LinkedHashMap<>();

	private List<GoalStatus> statuses = Collections.emptyList();
	private boolean ready;

	HowManyMorePanel(HowManyMorePlugin plugin, SkillIconManager skillIconManager)
	{
		this.plugin = plugin;
		this.skillIconManager = skillIconManager;
		setLayout(new BorderLayout(0, 12));
		setBorder(new EmptyBorder(10, 10, 10, 10));

		add(buildForm(), BorderLayout.NORTH);

		JPanel goalsSection = new JPanel(new BorderLayout(0, 6));
		goalsSection.setOpaque(false);
		goalsSection.add(heading("Your goals"), BorderLayout.NORTH);
		goalList.setOpaque(false);
		goalsSection.add(goalList, BorderLayout.CENTER);
		add(goalsSection, BorderLayout.CENTER);

		emptyLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		emptyLabel.setFont(FontManager.getRunescapeSmallFont());
		showGoals();
	}

	private JPanel buildForm()
	{
		// Older RuneLite still lists Overall as a skill. Matched by name, since Skill.OVERALL is going away.
		Skill[] skills = Arrays.stream(Skill.values())
			.filter(skill -> !"Overall".equals(skill.getName()))
			.sorted(Comparator.comparing(Skill::getName))
			.toArray(Skill[]::new);
		for (Skill skill : skills)
		{
			skillBox.addItem(skill);
		}
		skillBox.setRenderer(new DefaultListCellRenderer()
		{
			@Override
			public Component getListCellRendererComponent(JList<?> list, Object value, int index, boolean selected, boolean focused)
			{
				super.getListCellRendererComponent(list, value, index, selected, focused);
				if (value instanceof Skill)
				{
					Skill skill = (Skill) value;
					setText(skill.getName());
					setIcon(new ImageIcon(skillIconManager.getSkillImage(skill, true)));
				}
				return this;
			}
		});
		skillBox.setSelectedItem(Skill.AGILITY);
		skillBox.addActionListener(e -> resetNewMethod());

		targetField.putClientProperty("JTextField.placeholderText", "e.g. 70 or 1.5m");
		targetField.setToolTipText("A level (like 70) or an amount of XP (like 1,500,000 or 1.5m)");
		targetField.addActionListener(e -> addGoal());

		JButton addButton = new JButton("Add goal");
		addButton.addActionListener(e -> addGoal());

		errorLabel.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
		errorLabel.setFont(FontManager.getRunescapeSmallFont());

		JPanel form = new JPanel(new DynamicGridLayout(0, 1, 0, 4));
		form.setOpaque(false);
		form.add(heading("New goal"));
		form.add(skillBox);
		form.add(label("Target level or XP"));
		form.add(targetField);
		form.add(label("Method"));
		form.add(newMethod);
		form.add(addButton);
		form.add(errorLabel);
		resetNewMethod();
		return form;
	}

	// Called once the Skill Calculator's methods are read, so the pickers can list them.
	void catalogLoaded()
	{
		resetNewMethod();
		cards.clear();
		showGoals();
	}

	void update(List<GoalStatus> statuses, boolean ready)
	{
		boolean loggedIn = ready && !this.ready;
		this.statuses = statuses;
		this.ready = ready;
		if (loggedIn)
		{
			// The preselected method depends on the player's level, which is only known now.
			resetNewMethod();
		}
		showGoals();
	}

	private void showGoals()
	{
		List<String> ids = new ArrayList<>(statuses.size());
		for (GoalStatus status : statuses)
		{
			ids.add(status.getGoal().getId());
		}

		// Rebuild only when goals are added or removed, so an open method dropdown isn't closed by an XP drop.
		if (!ids.equals(new ArrayList<>(cards.keySet())))
		{
			cards.clear();
			goalList.removeAll();
			for (GoalStatus status : statuses)
			{
				GoalCard card = new GoalCard(plugin, skillIconManager, status);
				cards.put(status.getGoal().getId(), card);
				goalList.add(card);
			}
			if (statuses.isEmpty())
			{
				emptyLabel.setText(ready ? "No goals yet. Add one above." : "Log in to see your goals.");
				goalList.add(emptyLabel);
			}
			goalList.revalidate();
			goalList.repaint();
		}
		else if (statuses.isEmpty())
		{
			emptyLabel.setText(ready ? "No goals yet. Add one above." : "Log in to see your goals.");
		}

		for (GoalStatus status : statuses)
		{
			cards.get(status.getGoal().getId()).update(status);
		}
	}

	private void addGoal()
	{
		Skill skill = (Skill) skillBox.getSelectedItem();
		int targetXp = GoalMath.parseTarget(targetField.getText());
		String method = newMethod.getMethodId();
		double customXp = newMethod.getCustomXp();

		String error = null;
		if (skill == null)
		{
			error = "Pick a skill.";
		}
		else if (!plugin.isStatsReady())
		{
			error = "Log in to set goals.";
		}
		else if (targetXp < 0)
		{
			error = "Enter a level from 2 to 126, or an XP amount.";
		}
		else if (targetXp <= plugin.getXp(skill))
		{
			error = "You're already past that.";
		}
		else if (MethodCatalog.CUSTOM.equals(method) && customXp <= 0)
		{
			error = "Enter the XP you get each time.";
		}

		// A label with no text takes no room.
		errorLabel.setText(error);
		if (error != null)
		{
			return;
		}

		plugin.addGoal(skill, targetXp, method, customXp, newMethod.getBonusId());
		targetField.setText("");
	}

	// Lists the new skill's methods, preselecting the most advanced one the player can use.
	private void resetNewMethod()
	{
		Skill skill = (Skill) skillBox.getSelectedItem();
		if (skill == null)
		{
			return;
		}

		MethodCatalog catalog = plugin.getCatalog();
		int level = plugin.isStatsReady() ? Experience.getLevelForXp(plugin.getXp(skill)) : 1;
		MethodCatalog.Method best = catalog.best(skill, level);
		newMethod.setChoices(catalog.methods(skill), best == null ? MethodCatalog.AUTO : best.getId(), 0, null);
	}

	private static JLabel heading(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeBoldFont());
		label.setForeground(ColorScheme.BRAND_ORANGE);
		return label;
	}

	private static JLabel label(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		return label;
	}
}

package com.howmanymore;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.UUID;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "How Many More",
	description = "Counts down the laps, catches or other actions left to reach your skill goals, live on screen",
	tags = {"goal", "xp", "experience", "level", "skill", "calculator", "laps", "actions", "counter"}
)
public class HowManyMorePlugin extends Plugin
{
	private static final String GOALS_KEY = "goals";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private HowManyMoreConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private GoalOverlay overlay;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ItemManager itemManager;

	@Inject
	private SkillIconManager skillIconManager;

	@Inject
	private Notifier notifier;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private Gson gson;

	// Goals are only changed on the client thread; the HUD and sidebar read the statuses snapshot.
	private final List<Goal> goals = new ArrayList<>();
	private final int[] xp = new int[Skill.values().length];
	private final int[] lastDrop = new int[Skill.values().length];
	private final long[] lastGainMillis = new long[Skill.values().length];

	// False until the first tick after login, when the login stats have arrived.
	@Getter
	private volatile boolean statsReady;

	@Getter
	private volatile MethodCatalog catalog = MethodCatalog.EMPTY;

	@Getter
	private volatile List<GoalStatus> statuses = Collections.emptyList();

	private HowManyMorePanel panel;
	private NavigationButton navigationButton;

	@Provides
	HowManyMoreConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(HowManyMoreConfig.class);
	}

	@Override
	protected void startUp()
	{
		panel = new HowManyMorePanel(this, skillIconManager);
		navigationButton = NavigationButton.builder()
			.tooltip("How Many More")
			.icon(ImageUtil.loadImageResource(getClass(), "icon.png"))
			.priority(8)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navigationButton);
		overlayManager.add(overlay);

		clientThread.invoke(() ->
		{
			// Item-based method names need the game cache, which is loaded by the login screen.
			if (client.getGameState().getState() < GameState.LOGIN_SCREEN.getState())
			{
				return false;
			}

			catalog = MethodCatalog.load(itemManager);
			HowManyMorePanel goalPanel = panel;
			if (goalPanel != null)
			{
				SwingUtilities.invokeLater(goalPanel::catalogLoaded);
			}

			loadGoals();
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				readAllStats();
			}
			refresh();
			return true;
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		clientToolbar.removeNavigation(navigationButton);
		navigationButton = null;
		panel = null;
		goals.clear();
		statuses = Collections.emptyList();
		statsReady = false;
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		clientThread.invoke(() ->
		{
			loadGoals();
			refresh();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			statsReady = false;
			Arrays.fill(lastDrop, 0);
			Arrays.fill(lastGainMillis, 0);
			refresh();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!statsReady)
		{
			readAllStats();
			checkReached();
			refresh();
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		int skill = event.getSkill().ordinal();
		int previous = xp[skill];
		int gained = event.getXp() - previous;
		xp[skill] = event.getXp();
		if (!statsReady || gained <= 0)
		{
			return;
		}

		lastGainMillis[skill] = System.currentTimeMillis();
		// XP reads 0 before the login stats arrive, so don't count that jump as one action.
		if (previous > 0)
		{
			lastDrop[skill] = gained;
		}
		checkReached();
		refresh();
	}

	long millisSinceGain(Skill skill)
	{
		long last = lastGainMillis[skill.ordinal()];
		return last == 0 ? Long.MAX_VALUE : System.currentTimeMillis() - last;
	}

	// Safe to call from the sidebar: an int read is atomic and the value is refreshed every XP drop.
	int getXp(Skill skill)
	{
		return xp[skill.ordinal()];
	}

	void addGoal(Skill skill, int targetXp, String method, double customXp, @Nullable String bonus)
	{
		clientThread.invoke(() ->
		{
			Goal goal = new Goal();
			goal.setId(UUID.randomUUID().toString());
			goal.setSkill(skill);
			goal.setTargetXp(targetXp);
			goal.setStartXp(xp[skill.ordinal()]);
			goal.setMethod(method);
			goal.setCustomXp(customXp);
			goal.setBonus(bonus);
			goals.add(goal);
			saveGoals();
			refresh();
		});
	}

	void setMethod(String goalId, String method, double customXp, @Nullable String bonus)
	{
		clientThread.invoke(() ->
		{
			for (Goal goal : goals)
			{
				if (goal.getId().equals(goalId))
				{
					goal.setMethod(method);
					goal.setCustomXp(customXp);
					goal.setBonus(bonus);
				}
			}
			saveGoals();
			refresh();
		});
	}

	void removeGoal(String goalId)
	{
		clientThread.invoke(() ->
		{
			goals.removeIf(goal -> goal.getId().equals(goalId));
			saveGoals();
			refresh();
		});
	}

	private void readAllStats()
	{
		int[] experiences = client.getSkillExperiences();
		System.arraycopy(experiences, 0, xp, 0, Math.min(experiences.length, xp.length));
		statsReady = true;
	}

	private void checkReached()
	{
		boolean changed = false;
		for (Goal goal : goals)
		{
			if (goal.isReached() || xp[goal.getSkill().ordinal()] < goal.getTargetXp())
			{
				continue;
			}

			goal.setReached(true);
			changed = true;
			String message = "Goal reached: " + GoalMath.targetLabel(goal.getSkill(), goal.getTargetXp()) + "!";
			notifier.notify(config.goalReachedNotification(), message);
			chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.GAMEMESSAGE)
				.runeLiteFormattedMessage(new ChatMessageBuilder()
					.append(ChatColorType.HIGHLIGHT)
					.append(message)
					.build())
				.build());
		}

		if (changed)
		{
			saveGoals();
		}
	}

	private void refresh()
	{
		List<GoalStatus> next = new ArrayList<>(goals.size());
		for (Goal goal : goals)
		{
			next.add(status(goal));
		}
		statuses = Collections.unmodifiableList(next);

		HowManyMorePanel goalPanel = panel;
		boolean ready = statsReady;
		if (goalPanel != null)
		{
			SwingUtilities.invokeLater(() -> goalPanel.update(next, ready));
		}
	}

	private GoalStatus status(Goal goal)
	{
		Skill skill = goal.getSkill();
		String methodName = null;
		double xpEach = 0;
		if (MethodCatalog.CUSTOM.equals(goal.getMethod()))
		{
			xpEach = goal.getCustomXp();
		}
		else if (MethodCatalog.AUTO.equals(goal.getMethod()))
		{
			xpEach = lastDrop[skill.ordinal()];
		}
		else
		{
			MethodCatalog.Method method = catalog.method(skill, goal.getMethod());
			if (method != null)
			{
				MethodCatalog.Bonus bonus = MethodCatalog.bonus(method, goal.getBonus());
				methodName = method.getName();
				xpEach = method.getXp() * (bonus == null ? 1 : bonus.getMultiplier());
			}
		}

		int current = xp[skill.ordinal()];
		int xpLeft = GoalMath.xpLeft(current, goal.getTargetXp());
		return new GoalStatus(goal.copy(), methodName, xpEach, current, xpLeft, GoalMath.actionsLeft(xpLeft, xpEach),
			GoalMath.progress(goal.getStartXp(), current, goal.getTargetXp()));
	}

	private void loadGoals()
	{
		goals.clear();
		String json = configManager.getRSProfileConfiguration(HowManyMoreConfig.GROUP, GOALS_KEY);
		if (json == null)
		{
			return;
		}

		try
		{
			Goal[] saved = gson.fromJson(json, Goal[].class);
			if (saved == null)
			{
				return;
			}
			for (Goal goal : saved)
			{
				// A skill RuneLite no longer knows reads back as null.
				if (goal != null && goal.getId() != null && goal.getSkill() != null)
				{
					goals.add(goal);
				}
			}
		}
		catch (JsonParseException e)
		{
			log.warn("Couldn't read the saved goals", e);
		}
	}

	private void saveGoals()
	{
		if (goals.isEmpty())
		{
			configManager.unsetRSProfileConfiguration(HowManyMoreConfig.GROUP, GOALS_KEY);
		}
		else
		{
			configManager.setRSProfileConfiguration(HowManyMoreConfig.GROUP, GOALS_KEY, gson.toJson(goals));
		}
	}
}

package com.howmanymore;

import java.awt.Color;
import java.awt.Graphics;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Experience;

// Shades every other level on a goal's progress bar, so the level-ups still to come are easy to see.
final class LevelBands
{
	// Pixels a band must be wide; level-ups closer together than this share a band.
	private static final int MIN_WIDTH = 4;

	private LevelBands()
	{
	}

	// Paints the bands of a bar at x, y, right of fromX so they stay off its fill. They're worked out from the goal's
	// start, not the fill, so they stay put as you level.
	static void paint(Graphics g, Color shade, int startXp, int targetXp, int x, int y, int width, int height, int fromX)
	{
		List<Integer> edges = edges(startXp, targetXp, width);
		g.setColor(shade);
		// The bar starts plain, and each level-up kept switches between plain and shaded.
		for (int i = 0; i < edges.size(); i += 2)
		{
			int left = Math.max(edges.get(i), fromX);
			int right = i + 1 < edges.size() ? edges.get(i + 1) : width;
			if (right > left)
			{
				g.fillRect(x + left, y, right - left, height);
			}
		}
	}

	// Where each level-up between startXp and targetXp falls on a bar this wide. Any closer than MIN_WIDTH to the
	// last one kept, or to the bar's end, is left out.
	static List<Integer> edges(int startXp, int targetXp, int width)
	{
		List<Integer> edges = new ArrayList<>();
		if (targetXp <= startXp)
		{
			return edges;
		}
		int last = 0;
		for (int level = Experience.getLevelForXp(startXp) + 1; level <= Experience.MAX_VIRT_LEVEL; level++)
		{
			int xp = Experience.getXpForLevel(level);
			if (xp >= targetXp)
			{
				break;
			}
			int edge = (int) ((long) width * (xp - startXp) / (targetXp - startXp));
			if (edge - last >= MIN_WIDTH && width - edge >= MIN_WIDTH)
			{
				edges.add(edge);
				last = edge;
			}
		}
		return edges;
	}
}

package com.howmanymore;

import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import javax.annotation.Nullable;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Skill;
import net.runelite.client.game.ItemManager;

/**
 * The training methods for each skill and their XP per action, read from RuneLite's Skill Calculator so the values
 * stay current with RuneLite updates.
 */
@Slf4j
final class MethodCatalog
{
	static final String CUSTOM = "custom";
	static final String AUTO = "auto";

	static final MethodCatalog EMPTY = new MethodCatalog(new EnumMap<>(Skill.class));

	@Value
	static class Method
	{
		String id;
		String name;
		int level;
		double xp;
		List<Bonus> bonuses;
	}

	@Value
	static class Bonus
	{
		String id;
		String name;
		double multiplier;
	}

	private final Map<Skill, List<Method>> methods;

	MethodCatalog(Map<Skill, List<Method>> methods)
	{
		this.methods = methods;
	}

	// Must run on the client thread, because item-based method names come from item definitions.
	static MethodCatalog load(ItemManager itemManager)
	{
		try
		{
			return new MethodCatalog(CalculatorMethods.load(itemManager));
		}
		catch (LinkageError | RuntimeException e)
		{
			// The Skill Calculator isn't RuneLite API, so an update can move it; custom and auto goals still work.
			log.warn("Couldn't read the Skill Calculator's training methods", e);
			return EMPTY;
		}
	}

	List<Method> methods(Skill skill)
	{
		return methods.getOrDefault(skill, Collections.emptyList());
	}

	@Nullable
	Method method(Skill skill, @Nullable String id)
	{
		for (Method method : methods(skill))
		{
			if (method.getId().equals(id))
			{
				return method;
			}
		}
		return null;
	}

	@Nullable
	static Bonus bonus(Method method, @Nullable String id)
	{
		for (Bonus bonus : method.getBonuses())
		{
			if (bonus.getId().equals(id))
			{
				return bonus;
			}
		}
		return null;
	}

	// The most advanced method at or below the player's level, to preselect for a new goal.
	@Nullable
	Method best(Skill skill, int level)
	{
		Method best = null;
		for (Method method : methods(skill))
		{
			if (method.getLevel() <= level && (best == null || method.getLevel() >= best.getLevel()))
			{
				best = method;
			}
		}
		return best;
	}
}

package com.howmanymore;

import java.awt.BorderLayout;
import java.awt.event.FocusAdapter;
import java.awt.event.FocusEvent;
import java.util.List;
import java.util.function.Consumer;
import javax.annotation.Nullable;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextField;
import lombok.Value;
import net.runelite.client.ui.DynamicGridLayout;

// The method, bonus and custom XP choice for a goal, shared by the new-goal form and each goal card.
class MethodPicker extends JPanel
{
	@Value
	private static class MethodOption
	{
		String id;
		String label;
		@Nullable
		MethodCatalog.Method method;

		@Override
		public String toString()
		{
			return label;
		}
	}

	@Value
	private static class BonusOption
	{
		@Nullable
		MethodCatalog.Bonus bonus;

		@Override
		public String toString()
		{
			if (bonus == null)
			{
				return "No bonus";
			}
			double multiplier = bonus.getMultiplier();
			return bonus.getName() + (multiplier >= 1 && multiplier < 1.5
				? " (+" + GoalMath.formatXp((multiplier - 1) * 100) + "%)"
				: " (x" + GoalMath.formatXp(multiplier) + ")");
		}
	}

	private static final MethodOption CUSTOM = new MethodOption(MethodCatalog.CUSTOM, "Custom XP each", null);
	private static final MethodOption AUTO = new MethodOption(MethodCatalog.AUTO, "Auto (size of last XP drop)", null);

	private final JComboBox<MethodOption> methodBox = new JComboBox<>();
	private final JComboBox<BonusOption> bonusBox = new JComboBox<>();
	private final JPanel customRow = new JPanel(new BorderLayout(6, 0));
	private final JTextField customField = new JTextField();
	@Nullable
	private final Consumer<MethodPicker> onChange;
	// Set while the choices are filled in, so that doesn't count as the player changing them.
	private boolean filling;

	MethodPicker(@Nullable Consumer<MethodPicker> onChange)
	{
		this.onChange = onChange;
		setLayout(new DynamicGridLayout(0, 1, 0, 4));
		setOpaque(false);

		// Without a prototype the box is as wide as its longest method name and pushes the panel wider.
		methodBox.setPrototypeDisplayValue(new MethodOption("", "Razor-backed Kebbit (49)", null));
		bonusBox.setPrototypeDisplayValue(new BonusOption(null));
		methodBox.setToolTipText("The method you're training with");
		bonusBox.setToolTipText("An XP bonus from the Skill Calculator, like an outfit or altar");
		customField.setToolTipText("The XP you get each time");

		customRow.setOpaque(false);
		customRow.add(new JLabel("XP each"), BorderLayout.WEST);
		customRow.add(customField, BorderLayout.CENTER);

		add(methodBox);

		methodBox.addActionListener(e ->
		{
			if (!filling)
			{
				showExtras(null);
				changed();
			}
		});
		bonusBox.addActionListener(e ->
		{
			if (!filling)
			{
				changed();
			}
		});
		customField.addActionListener(e -> changed());
		customField.addFocusListener(new FocusAdapter()
		{
			@Override
			public void focusLost(FocusEvent e)
			{
				changed();
			}
		});
	}

	void setChoices(List<MethodCatalog.Method> methods, @Nullable String methodId, double customXp, @Nullable String bonusId)
	{
		filling = true;
		methodBox.removeAllItems();
		MethodOption selected = null;
		for (MethodCatalog.Method method : methods)
		{
			MethodOption option = new MethodOption(method.getId(), method.getName() + " (" + method.getLevel() + ")", method);
			methodBox.addItem(option);
			if (method.getId().equals(methodId))
			{
				selected = option;
			}
		}
		methodBox.addItem(CUSTOM);
		methodBox.addItem(AUTO);

		if (CUSTOM.getId().equals(methodId))
		{
			selected = CUSTOM;
		}
		else if (AUTO.getId().equals(methodId) || methodId == null)
		{
			selected = AUTO;
		}
		else if (selected == null)
		{
			// Keep a saved method the Skill Calculator no longer lists, so it isn't silently replaced.
			selected = new MethodOption(methodId, "Pick a method", null);
			methodBox.insertItemAt(selected, 0);
		}
		methodBox.setSelectedItem(selected);
		customField.setText(customXp > 0 ? GoalMath.formatXp(customXp) : "");
		showExtras(bonusId);
		filling = false;
	}

	String getMethodId()
	{
		MethodOption option = (MethodOption) methodBox.getSelectedItem();
		return option == null ? MethodCatalog.AUTO : option.getId();
	}

	double getCustomXp()
	{
		return GoalMath.parseXpEach(customField.getText());
	}

	@Nullable
	String getBonusId()
	{
		BonusOption option = (BonusOption) bonusBox.getSelectedItem();
		return option == null || option.getBonus() == null || bonusBox.getParent() != this ? null : option.getBonus().getId();
	}

	// Shows the bonus box when the method has bonuses, and the XP field for a custom method.
	private void showExtras(@Nullable String bonusId)
	{
		boolean wasFilling = filling;
		filling = true;
		MethodOption option = (MethodOption) methodBox.getSelectedItem();
		MethodCatalog.Method method = option == null ? null : option.getMethod();

		bonusBox.removeAllItems();
		bonusBox.addItem(new BonusOption(null));
		if (method != null)
		{
			for (MethodCatalog.Bonus bonus : method.getBonuses())
			{
				BonusOption bonusOption = new BonusOption(bonus);
				bonusBox.addItem(bonusOption);
				if (bonus.getId().equals(bonusId))
				{
					bonusBox.setSelectedItem(bonusOption);
				}
			}
		}
		// Removed rather than hidden, because the grid layout still leaves room for hidden rows.
		remove(bonusBox);
		remove(customRow);
		if (method != null && !method.getBonuses().isEmpty())
		{
			add(bonusBox);
		}
		if (CUSTOM.equals(option))
		{
			add(customRow);
		}
		filling = wasFilling;
		revalidate();
		repaint();
	}

	private void changed()
	{
		if (onChange != null)
		{
			onChange.accept(this);
		}
	}
}

package com.howmanymore;

import static org.junit.Assert.assertEquals;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import org.junit.Test;

public class GoalMathTest
{
	@Test
	public void countsRazorBackedKebbitsFrom50To70Hunter()
	{
		int xpLeft = GoalMath.xpLeft(101_333, 737_627);
		assertEquals(636_294, xpLeft);
		// 636,294 / 348 = 1,828.4, and a part catch still needs a whole catch.
		assertEquals(1_829, GoalMath.actionsLeft(xpLeft, 348));
	}

	@Test
	public void countsCanifisLapsFrom40To60Agility()
	{
		int xpLeft = GoalMath.xpLeft(Experience.getXpForLevel(40), Experience.getXpForLevel(60));
		assertEquals(986, GoalMath.actionsLeft(xpLeft, 240));
	}

	@Test
	public void exactMultipleNeedsNoExtraAction()
	{
		assertEquals(2, GoalMath.actionsLeft(480, 240));
		// Float XP like Varrock's 269.7 mustn't round 10 laps up to 11.
		assertEquals(10, GoalMath.actionsLeft(2_697, 269.7f));
		assertEquals(10, GoalMath.actionsLeft(2_697, Math.round(269.7f * 10) / 10.0));
	}

	@Test
	public void unknownXpEachHasNoCount()
	{
		assertEquals(-1, GoalMath.actionsLeft(1_000, 0));
	}

	@Test
	public void reachedGoalHasNothingLeft()
	{
		assertEquals(0, GoalMath.xpLeft(800_000, 737_627));
		assertEquals(0, GoalMath.actionsLeft(0, 348));
	}

	@Test
	public void progressRunsFromWhenTheGoalWasSet()
	{
		assertEquals(0, GoalMath.progress(1_000, 1_000, 3_000), 1e-9);
		assertEquals(0.5, GoalMath.progress(1_000, 2_000, 3_000), 1e-9);
		assertEquals(1, GoalMath.progress(1_000, 5_000, 3_000), 1e-9);
	}

	@Test
	public void parsesLevels()
	{
		assertEquals(737_627, GoalMath.parseTarget("70"));
		assertEquals(13_034_431, GoalMath.parseTarget(" 99 "));
		assertEquals(Experience.getXpForLevel(126), GoalMath.parseTarget("126"));
		assertEquals(-1, GoalMath.parseTarget("1"));
		assertEquals(-1, GoalMath.parseTarget("70.5"));
	}

	@Test
	public void parsesXpAmounts()
	{
		assertEquals(1_500_000, GoalMath.parseTarget("1.5m"));
		assertEquals(1_500_000, GoalMath.parseTarget("1,500,000"));
		assertEquals(500_000, GoalMath.parseTarget("500K"));
		assertEquals(200_000_000, GoalMath.parseTarget("200m"));
		assertEquals(-1, GoalMath.parseTarget("201m"));
		assertEquals(-1, GoalMath.parseTarget("lots"));
		assertEquals(-1, GoalMath.parseTarget(""));
		assertEquals(-1, GoalMath.parseTarget("-5"));
	}

	@Test
	public void labelsLevelAndXpTargets()
	{
		assertEquals(70, GoalMath.targetLevel(737_627));
		assertEquals(0, GoalMath.targetLevel(1_500_000));
		assertEquals("70 Hunter", GoalMath.targetLabel(Skill.HUNTER, 737_627));
		assertEquals("1.5M Agility XP", GoalMath.targetLabel(Skill.AGILITY, 1_500_000));
	}

	@Test
	public void formatsXpWithoutTrailingZeros()
	{
		assertEquals("348", GoalMath.formatXp(348));
		assertEquals("300", GoalMath.formatXp(300));
		assertEquals("269.7", GoalMath.formatXp(269.7));
		assertEquals("2.5", GoalMath.formatXp(2.5));
	}

	@Test
	public void parsesCustomXpEach()
	{
		assertEquals(348, GoalMath.parseXpEach("348"), 1e-9);
		assertEquals(1_234.5, GoalMath.parseXpEach(" 1,234.5 "), 1e-9);
		assertEquals(0, GoalMath.parseXpEach("abc"), 1e-9);
		assertEquals(0, GoalMath.parseXpEach("-4"), 1e-9);
	}
}

